/**
 * Generates src/assets/styles/components.scss — an index of every co-located
 * component stylesheet under src/_includes/components/.
 *
 * Replaces `bookshop-sass`, which discovered component SCSS automatically. The
 * generated file is @use'd into the normal sass pipeline, so adding a component
 * still needs no manual stylesheet registration.
 *
 * Each entry gets a unique namespace alias: component filenames repeat across
 * directories (two `hero.scss`, several `image.scss`), and sass rejects two
 * @use rules that resolve to the same default namespace.
 */
const fs = require("node:fs");
const path = require("node:path");

const COMPONENTS_DIR = path.join(__dirname, "..", "src", "_includes", "components");
const OUT_FILE = path.join(__dirname, "..", "src", "assets", "styles", "components.scss");

function findScss(dir) {
	if (!fs.existsSync(dir)) return [];
	return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) return findScss(full);
		return entry.isFile() && entry.name.endsWith(".scss") ? [full] : [];
	});
}

function build() {
	const files = findScss(COMPONENTS_DIR).sort();
	const outDir = path.dirname(OUT_FILE);

	const lines = files.map((file, i) => {
		// Sass wants POSIX separators and no extension.
		const rel = path
			.relative(outDir, file)
			.replace(/\\/g, "/")
			.replace(/\.scss$/, "");
		return `@use "${rel}" as c${i};`;
	});

	const contents = [
		"// GENERATED by utils/build-component-styles.js — do not edit.",
		`// ${files.length} component stylesheet${files.length === 1 ? "" : "s"}.`,
		"",
		...lines,
		"",
	].join("\n");

	fs.mkdirSync(outDir, { recursive: true });
	fs.writeFileSync(OUT_FILE, contents);
	console.log(`[component-styles] indexed ${files.length} stylesheets -> ${path.relative(process.cwd(), OUT_FILE)}`);
}

build();
